{"explanation":"The line of best fit (least-squares regression line) is the line ŷ = mx + b that makes the sum of squared vertical distances from the points to the line as small as possible. The slope is m = Σ(x−x̄)(y−ȳ) / Σ(x−x̄)², and the line always passes through the mean point (x̄, ȳ). Drag any yellow point and the line, the equation, and R² (how much of the variation in y the line explains) all update right away. Turn on residuals to see the vertical red gaps the line is minimizing. A single outlier can pull the line a long way.","manimCode":"const ax = new Axes({
  xRange: [0, 10, 1], yRange: [0, 10, 1],
  xLength: 8.5, yLength: 6, tips: false
});
ax.moveTo([-1.2, -0.4, 0]);
scene.add(ax);

// Linear map from screen -> data, derived from axes corners
const o = ax.c2p(0, 0);
const c = ax.c2p(10, 10);
const toData = (p) => [ (p[0] - o[0]) / (c[0] - o[0]) * 10, (p[1] - o[1]) / (c[1] - o[1]) * 10 ];

const initial = [[1, 2], [2, 2.8], [3, 3.5], [4, 5.2], [5, 4.6], [6, 6.3], [7, 6.9], [8, 8.1], [9, 8.4]];

// Residual segments (2-vertex polygons)
let showResiduals = false;
const residuals = initial.map(([x, y]) => {
  const seg = new Polygon({ vertices: [ax.c2p(x, y), ax.c2p(x, y + 0.01)], color: RED });
  seg.setStrokeWidth(2);
  seg.setFillOpacity(0);
  seg.setOpacity(0);
  return seg;
});
residuals.forEach(r => scene.add(r));

// Regression line
const fitLine = new Polygon({ vertices: [ax.c2p(0, 0), ax.c2p(10, 10)], color: BLUE });
fitLine.setStrokeWidth(4);
fitLine.setFillOpacity(0);
scene.add(fitLine);

// Mean point marker
const meanDot = new Dot({ point: ax.c2p(5, 5), color: GREEN, radius: 0.1 });
scene.add(meanDot);

// Draggable data points
const dots = initial.map(([x, y]) => new Dot({ point: ax.c2p(x, y), color: YELLOW, radius: 0.12 }));
dots.forEach(d => scene.add(d));

let eqLabel = null;
let r2Label = null;

function fmt(v) { return (Math.abs(v) < 0.005 ? 0 : v).toFixed(2); }

function update() {
  const pts = dots.map(d => toData(d.getCenter()));
  const n = pts.length;
  const mx = pts.reduce((s, p) => s + p[0], 0) / n;
  const my = pts.reduce((s, p) => s + p[1], 0) / n;
  let sxy = 0, sxx = 0, syy = 0;
  pts.forEach(([x, y]) => { sxy += (x - mx) * (y - my); sxx += (x - mx) ** 2; syy += (y - my) ** 2; });
  if (sxx < 1e-6) return;
  const m = sxy / sxx;
  const b = my - m * mx;

  // Clip line to the [0,10]x[0,10] box
  let x0 = 0, x1 = 10;
  if (Math.abs(m) > 1e-9) {
    const xa = (0 - b) / m, xb = (10 - b) / m;
    x0 = Math.max(0, Math.min(xa, xb));
    x1 = Math.min(10, Math.max(xa, xb));
  }
  if (x1 > x0) {
    fitLine.setVertices([ax.c2p(x0, m * x0 + b), ax.c2p(x1, m * x1 + b)]);
    fitLine.setOpacity(1);
  } else {
    fitLine.setOpacity(0);
  }
  meanDot.moveTo(ax.c2p(mx, my));

  pts.forEach(([x, y], i) => {
    const yh = Math.min(10, Math.max(0, m * x + b));
    residuals[i].setVertices([ax.c2p(x, y), ax.c2p(x, Math.abs(yh - y) < 0.01 ? y + 0.01 : yh)]);
    residuals[i].setOpacity(showResiduals ? 1 : 0);
  });

  const r2 = syy > 1e-9 ? (sxy * sxy) / (sxx * syy) : 1;

  if (eqLabel) scene.remove(eqLabel);
  if (r2Label) scene.remove(r2Label);
  const sign = b >= 0 ? '+' : '−';
  eqLabel = new Text({ text: 'ŷ = ' + fmt(m) + 'x ' + sign + ' ' + fmt(Math.abs(b)), color: BLUE, fontSize: 28 });
  eqLabel.moveTo([4.6, -1.6, 0]);
  r2Label = new Text({ text: 'R² = ' + r2.toFixed(3), color: WHITE, fontSize: 28 });
  r2Label.moveTo([4.6, -2.3, 0]);
  scene.add(eqLabel, r2Label);
}

dots.forEach(d => makeDraggable(d, scene, {
  constrainX: [o[0], c[0]],
  constrainY: [o[1], c[1]],
  onDrag: update
}));
dots.forEach(d => makeHoverable(d, scene, { hoverScale: 1.4 }));

const hint = new Text({ text: 'Drag the yellow points', color: GRAY, fontSize: 22 });
hint.moveTo([4.6, -3.0, 0]);
const meanNote = new Text({ text: '● mean (x̄, ȳ)', color: GREEN, fontSize: 20 });
meanNote.moveTo([4.6, -0.9, 0]);
scene.add(hint, meanNote);

update();

const controls = new Controls(scene, { position: 'top-right' });
controls.addCheckbox({ label: 'Show residuals', checked: false, onChange: (v) => { showResiduals = v; update(); } });
controls.addButton({ label: 'Reset points', onClick: () => {
  dots.forEach((d, i) => d.moveTo(ax.c2p(initial[i][0], initial[i][1])));
  update();
}});
controls.addButton({ label: 'Randomize', onClick: () => {
  dots.forEach(d => d.moveTo(ax.c2p(0.5 + Math.random() * 9, 0.5 + Math.random() * 9)));
  update();
}});

await scene.wait(999999);"}

